        _ id: String,
        _ category: ClearframeIconCategory,
        _ markup: String
    ) -> ClearframeIcon {
        ClearframeIcon(
            id: id,
            category: category,
            markup: markup,
            style: .emojiOne,
            box: VectorBox(x: 0, y: 0, width: 64, height: 64)
        )
    }
